import sys

def main():
    input = sys.stdin.read().strip().split()
    length = int(input[0])
    s = input[1]
    print(get_minimum_cost(list(s)))

INF = float('inf') / 3

def get_minimum_cost(sequence):
    v_positions = []
    k_positions = []
    other_positions = []

    for i, ch in enumerate(sequence):
        if ch == 'V':
            v_positions.append(i)
        elif ch == 'K':
            k_positions.append(i)
        else:
            other_positions.append(i)

    v_size = len(v_positions)
    k_size = len(k_positions)
    o_size = len(other_positions)

    # Initialize 4D DP array
    dp_table = [[[[INF for _ in range(o_size + 1)] for _ in range(k_size + 1)] for _ in range(v_size + 1)] for _ in range(2)]
    dp_table[0][0][0][0] = 0

    for v_count in range(v_size + 1):
        for k_count in range(k_size + 1):
            for o_count in range(o_size + 1):
                for last_flag in range(2):
                    current_cost = dp_table[last_flag][v_count][k_count][o_count]
                    if current_cost == INF:
                        continue
                    # Add V
                    if v_count < v_size:
                        new_cost = current_cost + count(v_positions[v_count], k_count, k_positions) + count(v_positions[v_count], o_count, other_positions)
                        if new_cost < dp_table[1][v_count + 1][k_count][o_count]:
                            dp_table[1][v_count + 1][k_count][o_count] = new_cost
                    # Add K
                    if k_count < k_size and last_flag == 0:
                        new_cost = current_cost + count(k_positions[k_count], v_count, v_positions) + count(k_positions[k_count], o_count, other_positions)
                        if new_cost < dp_table[0][v_count][k_count + 1][o_count]:
                            dp_table[0][v_count][k_count + 1][o_count] = new_cost
                    # Add other
                    if o_count < o_size:
                        new_cost = current_cost + count(other_positions[o_count], v_count, v_positions) + count(other_positions[o_count], k_count, k_positions)
                        if new_cost < dp_table[0][v_count][k_count][o_count + 1]:
                            dp_table[0][v_count][k_count][o_count + 1] = new_cost

    return min(dp_table[0][v_size][k_size][o_size], dp_table[1][v_size][k_size][o_size])

def count(position, start_idx, lst):
    cnt = 0
    for i in range(start_idx, len(lst)):
        if lst[i] < position:
            cnt += 1
    return cnt

if __name__ == "__main__":
    main()

